svg.script:
(function(){
  // === 4 步条件分支树：第一步选路线，第二步选对象，后续候选继续分叉 ===
  var FIRST_STEP = [
    {t:'能理解', p:44, i:12001},
    {t:'能生成', p:34, i:12002},
    {t:'会调用', p:22, i:12003}
  ];
  var SECOND_STEP = {
    '能理解': [
      {t:'自然语言', p:48, i:13001},
      {t:'业务资料', p:32, i:13002},
      {t:'复杂问题', p:20, i:13003}
    ],
    '能生成': [
      {t:'文章草稿', p:45, i:13101},
      {t:'创意图片', p:32, i:13102},
      {t:'会议纪要', p:23, i:13103}
    ],
    '会调用': [
      {t:'外部工具', p:46, i:13201},
      {t:'企业资料', p:34, i:13202},
      {t:'业务系统', p:20, i:13203}
    ]
  };
  var BRANCHES = {
    '能理解|自然语言': [
      [ {t:'并抓住意图', p:50, i:14001}, {t:'再提炼要点', p:30, i:14002}, {t:'还能改写表达', p:20, i:14003} ],
      [ {t:'的理解系统。', p:48, i:15001}, {t:'的沟通助手。', p:32, i:15002}, {t:'的认知工具。', p:20, i:15003} ]
    ],
    '能理解|业务资料': [
      [ {t:'并提取关键信息', p:48, i:14011}, {t:'再整理结构', p:32, i:14012}, {t:'还能发现关联', p:20, i:14013} ],
      [ {t:'的分析助手。', p:48, i:15011}, {t:'的知识助手。', p:32, i:15012}, {t:'的阅读助手。', p:20, i:15013} ]
    ],
    '能理解|复杂问题': [
      [ {t:'并拆解步骤', p:46, i:14021}, {t:'再比较方案', p:34, i:14022}, {t:'还能给出判断', p:20, i:14023} ],
      [ {t:'的推理工具。', p:48, i:15021}, {t:'的决策助手。', p:32, i:15022}, {t:'的 AI 模型。', p:20, i:15023} ]
    ],
    '能生成|文章草稿': [
      [ {t:'并按要求改写', p:48, i:14101}, {t:'再补充结构', p:32, i:14102}, {t:'还能调整语气', p:20, i:14103} ],
      [ {t:'的写作助手。', p:48, i:15101}, {t:'的内容工具。', p:32, i:15102}, {t:'的生成模型。', p:20, i:15103} ]
    ],
    '能生成|创意图片': [
      [ {t:'并形成画面', p:46, i:14111}, {t:'再变化风格', p:34, i:14112}, {t:'还能生成视频', p:20, i:14113} ],
      [ {t:'的视觉工具。', p:48, i:15111}, {t:'的创作工具。', p:32, i:15112}, {t:'的多模态能力。', p:20, i:15113} ]
    ],
    '能生成|会议纪要': [
      [ {t:'并整理待办', p:48, i:14121}, {t:'再标出责任人', p:32, i:14122}, {t:'还能生成摘要', p:20, i:14123} ],
      [ {t:'的办公助手。', p:48, i:15121}, {t:'的协作工具。', p:32, i:15122}, {t:'的效率工具。', p:20, i:15123} ]
    ],
    '会调用|外部工具': [
      [ {t:'并查询实时信息', p:48, i:14201}, {t:'再调用计算能力', p:32, i:14202}, {t:'还能生成结果', p:20, i:14203} ],
      [ {t:'的工具助手。', p:48, i:15201}, {t:'的执行系统。', p:32, i:15202}, {t:'的 Agent 能力。', p:20, i:15203} ]
    ],
    '会调用|企业资料': [
      [ {t:'并检索相关段落', p:48, i:14211}, {t:'再综合回答', p:32, i:14212}, {t:'还能标注来源', p:20, i:14213} ],
      [ {t:'的知识助手。', p:48, i:15211}, {t:'的问答系统。', p:32, i:15212}, {t:'的资料工具。', p:20, i:15213} ]
    ],
    '会调用|业务系统': [
      [ {t:'并分步骤执行', p:46, i:14221}, {t:'再根据结果调整', p:34, i:14222}, {t:'还能持续推进任务', p:20, i:14223} ],
      [ {t:'的任务助手。', p:48, i:15221}, {t:'的流程工具。', p:32, i:15222}, {t:'的执行系统。', p:20, i:15223} ]
    ]
  };
  var MAX_TOKENS = 4;
  var route = null;
  var objectChoice = null;

  var BASE = '大模型是一种';
  var step = 0;
  var acc = BASE;
  var lastToken = '_ROOT';
  var bubble = document.getElementById('aiBubble');
  var aiText = document.getElementById('aiText');
  var prog = document.getElementById('progressText');
  var ctxChip = document.getElementById('ctxChip');
  var complete = document.getElementById('completeOverlay');
  var finalSent = document.getElementById('finalSentence');
  var resetBtn = document.getElementById('resetBtn');

  function genCandidates(prev){
    if (step === 0) return FIRST_STEP;
    if (step === 1) return SECOND_STEP[route] || SECOND_STEP['能理解'];
    var key = route + '|' + objectChoice;
    var branch = BRANCHES[key] || BRANCHES['能理解|自然语言'];
    return branch[step - 2] || [];
  }

  function widthOf(t){
    if (t.length <= 2) return 30;
    if (t.length === 3) return 45;
    return 60;
  }

  function setBubbleText(text){
    var maxChars = 40;
    var lines = [];
    for (var i=0;i<text.length;i+=maxChars) lines.push(text.substring(i, i+maxChars));
    while (aiText.firstChild) aiText.removeChild(aiText.firstChild);
    lines.forEach(function(l, idx){
      var ts = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
      ts.setAttribute('x', '104');
      if (idx > 0) ts.setAttribute('dy', '20');
      ts.textContent = l;
      aiText.appendChild(ts);
    });
    var bw = lines.length > 1 ? 540 : Math.min(540, Math.max(120, text.length*14 + 30));
    var bh = 44 + (lines.length - 1) * 20;
    bubble.setAttribute('width', bw);
    bubble.setAttribute('height', bh);
  }
  function setFinalText(text){
    var maxChars = 34;
    var lines = [];
    for (var i=0;i<text.length;i+=maxChars) lines.push(text.substring(i, i+maxChars));
    while (finalSent.firstChild) finalSent.removeChild(finalSent.firstChild);
    lines.forEach(function(l, idx){
      var ts = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
      ts.setAttribute('x', '380');
      if (idx > 0) ts.setAttribute('dy', '18');
      ts.textContent = l;
      finalSent.appendChild(ts);
    });
  }

  function renderLayer(prev){
    var cands = genCandidates(prev);
    for (var k=0;k<3;k++){
      var row = document.getElementById('row' + k);
      if (!row) continue;
      var item = cands[k];
      row.setAttribute('class', 'row');
      if (!item){
        row.setAttribute('data-token', '');
        row.setAttribute('data-end', '');
        row.querySelector('.row-token').textContent = '—';
        row.querySelector('.row-pct').textContent = '';
        row.querySelector('.row-id').textContent = '';
        row.querySelector('.barfg').setAttribute('width', 0);
        continue;
      }
      row.setAttribute('data-token', item.t);
      row.setAttribute('data-w', widthOf(item.t));
      row.setAttribute('data-end', item.end ? '1' : '');
      row.querySelector('.row-token').textContent = item.t;
      row.querySelector('.row-pct').textContent = item.p + '%';
      row.querySelector('.row-id').textContent = item.end ? '#STOP' : '#' + item.i;
      row.querySelector('.barfg').setAttribute('width', 190 * item.p / 100);
    }
    ctxChip.textContent = '· P(t│' + (prev === '_ROOT' ? '∅' : prev) + ')';
    ctxChip.setAttribute('display', 'inline');
  }

  function finish(){
    document.getElementById('candLayer').setAttribute('display', 'none');
    ctxChip.setAttribute('display', 'none');
    complete.setAttribute('display', 'inline');
    resetBtn.setAttribute('display', 'inline');
    setFinalText(acc);
    prog.textContent = '生成完成 ✓ · ' + step + ' tokens';
  }

  function pickRow(row){
    var token = row.getAttribute('data-token');
    if (!token) return;
    var isEnd = row.getAttribute('data-end') === '1';
    row.setAttribute('class', 'row picked');
    setTimeout(function(){
      if (isEnd){ finish(); return; }
      acc = acc + token;
      if (step === 0) route = token;
      if (step === 1) objectChoice = token;
      setBubbleText(acc);
      lastToken = token;
      step++;
      if (step >= MAX_TOKENS) { finish(); return; }
      prog.textContent = 'TOKEN #' + (step+1) + ' / 4 · 沿着这条路线继续';
      renderLayer(lastToken);
    }, 220);
  }

  function bindRows(){
    for (var i=0;i<3;i++){
      (function(r){ r.addEventListener('click', function(){ pickRow(r); }); })(document.getElementById('row' + i));
    }
  }
  function reset(){
    step = 0;
    acc = BASE;
    lastToken = '_ROOT';
    route = null;
    objectChoice = null;
    setBubbleText(BASE);
    prog.textContent = 'TOKEN #1 / 4 · 选择一条路线';
    complete.setAttribute('display', 'none');
    resetBtn.setAttribute('display', 'none');
    document.getElementById('candLayer').setAttribute('display', 'inline');
    renderLayer('_ROOT');
  }

  resetBtn.addEventListener('click', reset);
  bindRows();
  setBubbleText(BASE);
  renderLayer('_ROOT');
})();
